		}

		if (skb == NULL) {
			stats->rx_dropped++;
			return;
		}

		cfd->can_id = id & ESD_USB_IDMASK;

		if (msg->rx.dlc & ESD_USB_FD) {
			/* masking by 0x0F is already done within can_fd_dlc2len() */
			cfd->len = can_fd_dlc2len(msg->rx.dlc);
			len = cfd->len;
			if ((msg->rx.dlc & ESD_USB_NO_BRS) == 0)
				cfd->flags |= CANFD_BRS;
			if (msg->rx.dlc & ESD_USB_ESI)
