				len = 0;
			}
		}

		if (id & ESD_USB_EXTID)
			cfd->can_id |= CAN_EFF_FLAG;

		memcpy(cfd->data, msg->rx.data_fd, len);
		stats->rx_bytes += len;
		stats->rx_packets++;

