{
	int maxwork = 1024;
	while (len) {
		if (!(maxwork--)) {
			pr_err("too much work\n");
			break;
		}

		switch (ttusb->mux_state) {
		case 0:
		case 1:
		case 2:
			len--;
			if (*data++ == 0xAA)
				++ttusb->mux_state;
			else {
				ttusb->mux_state = 0;
				if (ttusb->insync) {
					pr_info("lost sync.\n");
